# App manager - generated by vexelray-installer. Do not edit by hand; regenerate it.
# vi-manager-rev: 1
#
# One window for everything installed through vexelray-installer on this computer (the install records in
# the registry directory): what is installed, what is newer, and Update, Change (folder, shortcuts, PATH,
# file types), Remove and Update all. Each install ships this script; the newest copy is kept beside the
# registry directory (manager\manager.ps1) with a Start menu shortcut, so it outlives any one application.
#
# The manager never changes an install itself. It runs that application's own install.ps1 (downloaded and
# checked against the SHA-256 in its manifest) or uninstall.ps1 in a separate, quiet PowerShell process, one
# at a time, and follows it through the "##vi" event lines it prints (INSTALL_EVENTS=1). A failed run is
# rolled back by the installer's journal, whatever happens to this window.
#
#   manager.cmd                    open the window (in Edge, as an app; -Forms for the plain Windows one)
#   manager.cmd -List              list the installs and whether a newer version is published
#   manager.cmd -Update <id>       update one in the console; -UpdateAll updates every one that is behind
#   manager.cmd -Remove <id>       remove one in the console
#   add -CloseApps to close what is running from an install folder first

$InstallerCfg = '{"id":"mainframe","name":"MainFrame","publisher":"sibarum","description":"A terminal window that wraps the native Windows shell over ConPTY, built on the VexelRay stack.","manifestUrl":"https://raw.githubusercontent.com/sibarum/vexelray-dist/main/apps/mainframe/manifest.json","registryDir":"%LOCALAPPDATA%\\vexelray-installer\\installs","issuesUrl":"https://github.com/sibarum/vexelray-dist/issues/new"}' | ConvertFrom-Json

function ViExpand([string]$p) { [Environment]::ExpandEnvironmentVariables($p) }
function ViSha([string]$p) { (Get-FileHash -Algorithm SHA256 -LiteralPath $p).Hash.ToLowerInvariant() }
function ViRegistryDir {
    if ($env:INSTALL_REGISTRY_DIR) { return $env:INSTALL_REGISTRY_DIR }
    ViExpand $InstallerCfg.registryDir
}

function ViVerKey([string]$v) {
    $core = ($v -replace '^[vV]', '') -replace '[-+].*$', ''
    if ($core -notmatch '\.') { $core = "$core.0" }
    try { $ver = [version]$core } catch { $ver = [version]'0.0' }
    [pscustomobject]@{ Ver = $ver; Pre = [bool]($v -match '-') }
}
function ViCompare([string]$a, [string]$b) {
    $x = ViVerKey $a; $y = ViVerKey $b
    $c = $x.Ver.CompareTo($y.Ver)
    if ($c -ne 0) { return $c }
    if ($x.Pre -and -not $y.Pre) { return -1 }
    if (-not $x.Pre -and $y.Pre) { return 1 }
    return 0
}

# Processes started from a folder (by path, or with it on their command line), leaving out this one and its
# parents. The same rule the installer uses before it replaces a file in use.
function ViRunningFrom([string]$dir) {
    $root = $dir.TrimEnd('\') + '\'
    $all = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue)
    $byId = @{}
    foreach ($p in $all) { $byId[[int]$p.ProcessId] = $p }
    $mine = @{}
    $c = [int]$PID
    while ($c -and $byId.ContainsKey($c) -and -not $mine.ContainsKey($c)) { $mine[$c] = $true; $c = [int]$byId[$c].ParentProcessId }
    @($all | Where-Object {
        -not $mine.ContainsKey([int]$_.ProcessId) -and (
            ($_.ExecutablePath -and $_.ExecutablePath.StartsWith($root, [StringComparison]::OrdinalIgnoreCase)) -or
            ($_.CommandLine -and $_.CommandLine.IndexOf($root, [StringComparison]::OrdinalIgnoreCase) -ge 0))
    })
}

# ---- model -----------------------------------------------------------------------------
# $M holds everything a front end shows; Rev goes up whenever any of it changes, and a front end redraws
# when it sees a new Rev. Actions only queue jobs (ViEnqueue); ViPump, called every tick, moves them along.

$M = @{
    Apps = [ordered]@{}
    Log = New-Object 'System.Collections.Generic.List[string]'
    Queue = New-Object 'System.Collections.Generic.List[object]'
    Job = $null
    Rev = 0
    Status = ''
    Progress = -1
    Pumping = $false
}
Add-Type -AssemblyName System.Net.Http
$ViHttp = New-Object Net.Http.HttpClient
$ViHttp.DefaultRequestHeaders.UserAgent.ParseAdd('vexelray-installer')
[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

function ViChanged { $M.Rev++ }
function ViLog([string]$text) {
    $M.Log.Add($text)
    if ($M.Log.Count -gt 2000) { $M.Log.RemoveRange(0, $M.Log.Count - 2000) }
    ViChanged
}

function ViReadRecords {
    $dir = ViRegistryDir
    $out = @()
    if (-not (Test-Path -LiteralPath $dir)) { return $out }
    foreach ($f in Get-ChildItem -LiteralPath $dir -Filter *.json -File) {
        try {
            $r = Get-Content -Raw -LiteralPath $f.FullName | ConvertFrom-Json
            if ($r.id -and $r.installDir) { $out += $r }
        } catch { }
    }
    $out
}

# Reads the records again, keeping what is known about each manifest, and checks the manifests (in the
# background) of the ones named, or of all of them.
function ViLoad([string[]]$check) {
    $seen = @{}
    foreach ($r in ViReadRecords) {
        $seen[$r.id] = $true
        $a = $M.Apps[$r.id]
        if (-not $a) {
            $a = [pscustomobject]@{ Id = $r.id; Name = $r.name; Record = $r; Manifest = $null; Latest = $null; Fetch = $null; State = 'checking'; Message = 'Checking for updates...' }
            $M.Apps[$r.id] = $a
            $check += $r.id
        }
        $a.Record = $r; $a.Name = $r.name
    }
    foreach ($k in @($M.Apps.Keys)) { if (-not $seen[$k]) { $M.Apps.Remove($k) } }
    foreach ($a in $M.Apps.Values) {
        if ($check -contains $a.Id -or $check -contains '*') {
            if ($a.Record.manifestUrl) {
                $a.Fetch = $ViHttp.GetStringAsync($a.Record.manifestUrl)
                $a.State = 'checking'; $a.Message = 'Checking for updates...'
            } else { $a.State = 'unknown'; $a.Message = 'No manifest recorded' }
        }
    }
    ViChanged
}

function ViPumpFetches {
    foreach ($a in $M.Apps.Values) {
        if (-not $a.Fetch -or -not $a.Fetch.IsCompleted) { continue }
        $t = $a.Fetch; $a.Fetch = $null
        if ($t.Status -ne 'RanToCompletion') {
            $why = if ($t.Exception) { $t.Exception.GetBaseException().Message } else { 'cancelled' }
            $a.State = 'error'; $a.Message = "Could not check for updates: $why"
        } else {
            try {
                $a.Manifest = $t.Result | ConvertFrom-Json
                $a.Latest = $a.Manifest.latest
                if ((ViCompare $a.Latest $a.Record.version) -gt 0) { $a.State = 'update'; $a.Message = "$($a.Latest) is available" }
                else { $a.State = 'current'; $a.Message = 'Up to date' }
            } catch { $a.State = 'error'; $a.Message = "The manifest could not be read: $($_.Exception.Message)" }
        }
        if ($M.Job -and $M.Job.Id -eq $a.Id) { $a.State = 'busy' }
        ViChanged
    }
}

# The manifest's entry for a version, and which choices apply to it (shortcuts, PATH, file types).
function ViChoices($a, [string]$version) {
    $c = [ordered]@{ shortcuts = $true; path = $true; assoc = $true }
    if (-not $a.Manifest) { return $c }
    $e = @($a.Manifest.versions) | Where-Object { $_.version -eq $version } | Select-Object -First 1
    $bins = @($e.platforms.windows.binaries)
    if (-not $e) { return $c }
    $c.shortcuts = @($bins | Where-Object { $_.shortcuts }).Count -gt 0
    $c.path = @($bins | Where-Object { $_.addToPath }).Count -gt 0
    $c.assoc = @($bins | ForEach-Object { @($_.fileAssociations) } | Where-Object { $_ }).Count -gt 0
    $c
}

# ---- jobs ------------------------------------------------------------------------------
# kind: update (to the latest), change (same version; Options: dir, noShortcuts, noPath, noAssociations),
# remove. CloseApps: the user agreed to close what is running from the install folder.

function ViEnqueue([string]$kind, [string]$id, $options, [bool]$closeApps) {
    $a = $M.Apps[$id]
    if (-not $a) { return }
    if ($M.Job -and $M.Job.Id -eq $id) { return }
    if (@($M.Queue | Where-Object { $_.Id -eq $id }).Count -gt 0) { return }
    $M.Queue.Add([pscustomobject]@{ Kind = $kind; Id = $id; Options = $options; CloseApps = $closeApps })
    $a.State = 'queued'; $a.Message = "Waiting to $kind"
    ViChanged
}

# Updates first what others depend on, so a runtime is new before the applications that need it.
function ViUpdateAll([bool]$closeApps) {
    $todo = @($M.Apps.Values | Where-Object { $_.State -eq 'update' })
    while ($todo.Count -gt 0) {
        $ids = @($todo | ForEach-Object { $_.Id })
        $next = @($todo | Where-Object { @(@($_.Record.requires) | Where-Object { $_ -and $ids -contains $_ }).Count -eq 0 })
        if ($next.Count -eq 0) { $next = $todo }
        foreach ($n in $next) { ViEnqueue 'update' $n.Id $null $closeApps }
        $nextIds = @($next | ForEach-Object { $_.Id })
        $todo = @($todo | Where-Object { $nextIds -notcontains $_.Id })
    }
}

function ViStartJob($q) {
    $a = $M.Apps[$q.Id]
    if (-not $a) { return }
    $r = $a.Record
    $job = [pscustomobject]@{ Id = $q.Id; Kind = $q.Kind; Proc = $null; Out = $null; Err = $null; Script = $null; Phase = 'start'; LastError = $null; Cancelled = $false }
    $M.Job = $job
    $a.State = 'busy'
    $M.Progress = -1
    $verb = @{ update = 'Updating'; change = 'Changing'; remove = 'Removing' }[$q.Kind]
    $M.Status = "$verb $($a.Name)"
    ViLog "==> $verb $($a.Name)"
    try {
        $psi = New-Object Diagnostics.ProcessStartInfo
        $psi.FileName = Join-Path $env:windir 'System32\WindowsPowerShell\v1.0\powershell.exe'
        $psi.UseShellExecute = $false
        $psi.CreateNoWindow = $true
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        foreach ($n in 'INSTALL_VERSION', 'INSTALL_DIR', 'INSTALL_FORCE', 'INSTALL_NO_SHORTCUTS', 'INSTALL_NO_PATH', 'INSTALL_NO_ASSOCIATIONS', 'INSTALL_CLOSE_APPS', 'INSTALL_ONLY') {
            [void]$psi.EnvironmentVariables.Remove($n)
        }
        $psi.EnvironmentVariables['INSTALL_QUIET'] = '1'
        $psi.EnvironmentVariables['INSTALL_EVENTS'] = '1'
        if ($q.CloseApps) { $psi.EnvironmentVariables['INSTALL_CLOSE_APPS'] = '1' }
        if ($q.Kind -eq 'remove') {
            $script = Join-Path $r.installDir 'uninstall.ps1'
            if (-not (Test-Path -LiteralPath $script)) { $script = ViFetchTool $a 'uninstall.ps1'; $job.Script = $script }
            $psi.Arguments = "-NoProfile -ExecutionPolicy Bypass -File `"$script`" -Id $($r.id) -Yes"
        } else {
            $script = ViFetchTool $a 'install.ps1'
            $job.Script = $script
            if ($q.Kind -eq 'update') {
                $psi.Arguments = "-NoProfile -ExecutionPolicy Bypass -File `"$script`" -Version $($a.Latest) -Dir `"$($r.installDir)`" -Force"
            } else {
                $o = $q.Options
                $dir = if ($o.dir) { $o.dir } else { $r.installDir }
                foreach ($p in @(@('noShortcuts', 'INSTALL_NO_SHORTCUTS'), @('noPath', 'INSTALL_NO_PATH'), @('noAssociations', 'INSTALL_NO_ASSOCIATIONS'))) {
                    if ($null -ne $o.($p[0])) { $psi.EnvironmentVariables[$p[1]] = $(if ($o.($p[0])) { '1' } else { '0' }) }
                }
                $psi.Arguments = "-NoProfile -ExecutionPolicy Bypass -File `"$script`" -Version $($r.version) -Dir `"$($dir.TrimEnd('\'))`" -Force"
            }
        }
        $job.Proc = [Diagnostics.Process]::Start($psi)
        $job.Out = $job.Proc.StandardOutput.ReadLineAsync()
        $job.Err = $job.Proc.StandardError.ReadLineAsync()
    } catch {
        ViLog "ERROR: $($_.Exception.Message)"
        ViEndJob $job $false $_.Exception.Message
    }
    ViChanged
}

# The application's own copy of a tool, from its manifest, checked against the SHA-256 recorded there.
function ViFetchTool($a, [string]$name) {
    if (-not $a.Manifest) { throw "The manifest of $($a.Name) could not be read, so its $name cannot be fetched. Try Refresh." }
    $t = $a.Manifest.tools.$name
    if (-not $t -or -not $t.url -or -not $t.sha256) { throw "The manifest of $($a.Name) names no $name." }
    $p = Join-Path ([IO.Path]::GetTempPath()) ("vi-manager-" + [guid]::NewGuid().ToString('N').Substring(0, 8) + "-$name")
    $w = New-Object Net.WebClient
    $w.Headers['User-Agent'] = 'vexelray-installer'
    try { $w.DownloadFile($t.url, $p) } finally { $w.Dispose() }
    if ((ViSha $p) -ne $t.sha256) { Remove-Item -Force -LiteralPath $p; throw "The $name downloaded from $($t.url) does not match the SHA-256 in the manifest; it was not run." }
    $p
}

function ViJobLine([string]$line) {
    if ($null -eq $line) { return }
    if ($line.StartsWith('##vi ')) {
        try { $e = $line.Substring(5) | ConvertFrom-Json } catch { return }
        switch ($e.e) {
            'phase' { $M.Job.Phase = $e.p; ViChanged }
            'step' { $M.Status = "$($M.Apps[$M.Job.Id].Name): $($e.m)"; $M.Progress = -1; ViChanged }
            'progress' {
                if ($e.total -gt 0) { $M.Progress = [int](100 * $e.done / $e.total) }
                $M.Status = "$($M.Apps[$M.Job.Id].Name): downloading {0} ({1:N1} of {2:N1} MB)" -f $e.label, ($e.done / 1MB), ($e.total / 1MB)
                ViChanged
            }
        }
        return
    }
    if ($line -match '^ERROR: (.*)') { $M.Job.LastError = $Matches[1] }
    ViLog $line
}

function ViPumpJob {
    $job = $M.Job
    if (-not $job -or -not $job.Proc) { return }
    for ($i = 0; $i -lt 200; $i++) {
        $got = $false
        if ($job.Out -and $job.Out.IsCompleted) {
            $l = $job.Out.Result
            if ($null -eq $l) { $job.Out = $null } else { ViJobLine $l; $job.Out = $job.Proc.StandardOutput.ReadLineAsync() }
            $got = $true
        }
        if ($job.Err -and $job.Err.IsCompleted) {
            $l = $job.Err.Result
            if ($null -eq $l) { $job.Err = $null } else { if ($l.Trim()) { ViLog $l }; $job.Err = $job.Proc.StandardError.ReadLineAsync() }
            $got = $true
        }
        if (-not $got) { break }
    }
    if (-not $job.Out -and -not $job.Err -and $job.Proc.HasExited) {
        $ok = $job.Proc.ExitCode -eq 0 -and -not $job.Cancelled
        $msg = if ($job.Cancelled) { 'Cancelled' } elseif ($job.LastError) { $job.LastError } else { "The installer exited with code $($job.Proc.ExitCode)." }
        ViEndJob $job $ok $msg
    }
}

function ViEndJob($job, [bool]$ok, [string]$msg) {
    if ($job.Script -and (Test-Path -LiteralPath $job.Script)) { Remove-Item -Force -LiteralPath $job.Script -ErrorAction SilentlyContinue }
    $M.Job = $null
    $M.Progress = -1
    $name = $M.Apps[$job.Id].Name
    $verb = @{ update = 'Updated'; change = 'Changed'; remove = 'Removed' }[$job.Kind]
    if ($ok) { ViLoad @($job.Id) } else { ViLoad @() }
    $a = $M.Apps[$job.Id]
    if ($ok) { $M.Status = "$verb $name"; ViLog "    $verb $name." }
    else {
        $M.Status = "${name}: $msg"
        # the failure stays on the row until the next check (the install was rolled back to the version shown)
        if ($a) { $a.Fetch = $null; $a.Message = $msg; $a.State = 'error' }
    }
    ViChanged
}

# Stops the running job while it is only downloading (nothing is placed yet); later it runs to its end.
function ViCancel {
    $job = $M.Job
    if ($job -and $job.Proc -and -not $job.Proc.HasExited -and $job.Phase -ne 'busy') {
        $job.Cancelled = $true
        try { $job.Proc.Kill() } catch { }
        ViLog '    Cancelled.'
    }
    $ids = @($M.Queue | ForEach-Object { $_.Id })
    $M.Queue.Clear()
    if ($ids.Count -gt 0) { ViLoad $ids }
}

function ViPump {
    if ($M.Pumping) { return }
    $M.Pumping = $true
    try {
        ViPumpFetches
        if ($M.Job) { ViPumpJob }
        if (-not $M.Job -and $M.Queue.Count -gt 0) {
            $q = $M.Queue[0]
            $M.Queue.RemoveAt(0)
            ViStartJob $q
        }
    } catch { ViLog "ERROR: $($_.Exception.Message)" }
    finally { $M.Pumping = $false }
}

# ---- window ----------------------------------------------------------------------------
# WinForms, run by Application.Run; a timer pumps the model and redraws on a new Rev. Handlers are plain
# script blocks here (not closures), so they reach $M and the Vi* functions directly.

function ViAskRunning($a, [string]$what) {
    $procs = @(ViRunningFrom $a.Record.installDir)
    if ($procs.Count -eq 0) { return 'none' }
    $names = ($procs | ForEach-Object { "$($_.Name) (process $($_.ProcessId))" }) -join "`n"
    $buttons = if ($what -eq 'remove') { 'OKCancel' } else { 'YesNoCancel' }
    $text = if ($what -eq 'remove') { "$($a.Name) is running:`n`n$names`n`nIt will be closed before it is removed." }
            else { "$($a.Name) is running:`n`n$names`n`nClose it first? (No: files it is not using are replaced now, and it is updated when it next starts.)" }
    $r = [Windows.Forms.MessageBox]::Show($ViForm, $text, $ViForm.Text, [Windows.Forms.MessageBoxButtons]$buttons, [Windows.Forms.MessageBoxIcon]::Question)
    switch ([string]$r) { 'Yes' { 'close' } 'OK' { 'close' } 'No' { 'keep' } default { 'cancel' } }
}

function ViSelected {
    if ($ViList.SelectedItems.Count -eq 0) { return $null }
    $M.Apps[[string]$ViList.SelectedItems[0].Tag]
}

function ViChangeDialog($a) {
    $r = $a.Record
    $c = ViChoices $a $r.version
    $d = New-Object Windows.Forms.Form
    $d.AutoScaleDimensions = New-Object Drawing.SizeF(96, 96); $d.AutoScaleMode = 'Dpi'
    $d.Font = New-Object Drawing.Font('Segoe UI', 9)
    $d.Text = "Change $($a.Name)"; $d.FormBorderStyle = 'FixedDialog'; $d.MaximizeBox = $false; $d.MinimizeBox = $false
    $d.StartPosition = 'CenterParent'; $d.ClientSize = New-Object Drawing.Size(520, 230)
    $l = New-Object Windows.Forms.Label; $l.Text = 'Install folder (it is moved when this changes)'; $l.AutoSize = $true; $l.Location = New-Object Drawing.Point(16, 14)
    $t = New-Object Windows.Forms.TextBox; $t.Text = $r.installDir; $t.Location = New-Object Drawing.Point(16, 36); $t.Size = New-Object Drawing.Size(488, 25)
    $boxes = @()
    $y = 76
    foreach ($row in @(@('shortcuts', 'Shortcuts on the desktop / in the Start menu', 'noShortcuts'), @('path', 'On the user PATH', 'noPath'), @('assoc', 'Opens its file types', 'noAssociations'))) {
        $cb = New-Object Windows.Forms.CheckBox
        $cb.Text = $row[1]; $cb.AutoSize = $true; $cb.Location = New-Object Drawing.Point(18, $y); $cb.Tag = $row[2]
        $cb.Checked = -not [bool]$r.options.($row[2]); $cb.Enabled = [bool]$c[$row[0]]
        $boxes += $cb; $y += 28
    }
    $ok = New-Object Windows.Forms.Button; $ok.Text = 'Apply'; $ok.DialogResult = 'OK'; $ok.Location = New-Object Drawing.Point(318, 186); $ok.Size = New-Object Drawing.Size(90, 28)
    $no = New-Object Windows.Forms.Button; $no.Text = 'Cancel'; $no.DialogResult = 'Cancel'; $no.Location = New-Object Drawing.Point(414, 186); $no.Size = New-Object Drawing.Size(90, 28)
    $d.Controls.AddRange(@($l, $t, $ok, $no) + $boxes)
    $d.AcceptButton = $ok; $d.CancelButton = $no
    try {
        if ($d.ShowDialog($ViForm) -ne 'OK') { return $null }
        $o = [ordered]@{ dir = $t.Text.Trim() }
        foreach ($cb in $boxes) { if ($cb.Enabled) { $o[$cb.Tag] = -not $cb.Checked } }
        [pscustomobject]$o
    } finally { $d.Dispose() }
}

function ViAct([string]$kind) {
    if ($kind -eq 'all') {
        $up = @($M.Apps.Values | Where-Object { $_.State -eq 'update' })
        if ($up.Count -eq 0) { return }
        $close = $false
        foreach ($a in $up) {
            $ans = ViAskRunning $a 'update'
            if ($ans -eq 'cancel') { return }
            if ($ans -eq 'close') { $close = $true }
        }
        ViUpdateAll $close
        return
    }
    $a = ViSelected
    if (-not $a) { return }
    $opts = $null
    if ($kind -eq 'remove') {
        $r = [Windows.Forms.MessageBox]::Show($ViForm, "Remove $($a.Name) $($a.Record.version) from $($a.Record.installDir)?", $ViForm.Text,
            [Windows.Forms.MessageBoxButtons]::OKCancel, [Windows.Forms.MessageBoxIcon]::Warning, [Windows.Forms.MessageBoxDefaultButton]::Button2)
        if ([string]$r -ne 'OK') { return }
    }
    if ($kind -eq 'change') { $opts = ViChangeDialog $a; if (-not $opts) { return } }
    $ans = ViAskRunning $a $kind
    if ($ans -eq 'cancel') { return }
    ViEnqueue $kind $a.Id $opts ($ans -eq 'close')
}

function ViRender {
    if ($ViForm.IsDisposed) { return }
    $sel = if ($ViList.SelectedItems.Count) { [string]$ViList.SelectedItems[0].Tag } else { $null }
    $ViList.BeginUpdate()
    $ViList.Items.Clear()
    foreach ($a in $M.Apps.Values) {
        $it = New-Object Windows.Forms.ListViewItem($a.Name)
        $it.Tag = $a.Id
        [void]$it.SubItems.Add([string]$a.Record.version)
        [void]$it.SubItems.Add($(if ($a.Latest) { [string]$a.Latest } else { '' }))
        [void]$it.SubItems.Add([string]$a.Message)
        if ($a.State -eq 'update') { $it.Font = New-Object Drawing.Font($ViList.Font, [Drawing.FontStyle]::Bold) }
        if ($a.State -eq 'error') { $it.ForeColor = [Drawing.Color]::FromArgb(176, 0, 32) }
        [void]$ViList.Items.Add($it)
        if ($a.Id -eq $sel) { $it.Selected = $true }
    }
    if (-not $sel -and $ViList.Items.Count) { $ViList.Items[0].Selected = $true }
    $ViList.Columns[3].Width = -2
    $ViList.EndUpdate()
    $ViEmpty.Visible = $M.Apps.Count -eq 0
    $a = ViSelected
    $idle = $a -and $a.State -notin 'busy', 'queued'
    $ViBtn.update.Enabled = $idle -and $a.State -eq 'update'
    $ViBtn.change.Enabled = [bool]($idle -and $a.Manifest)
    $ViBtn.remove.Enabled = [bool]$idle
    $ViBtn.all.Enabled = @($M.Apps.Values | Where-Object { $_.State -eq 'update' }).Count -gt 0
    $ViBtn.cancel.Enabled = [bool]($M.Job -and $M.Job.Phase -ne 'busy') -or $M.Queue.Count -gt 0
    $ViStatus.Text = $M.Status
    if ($M.Progress -lt 0) { $ViBar.Style = $(if ($M.Job) { 'Marquee' } else { 'Continuous' }); if (-not $M.Job) { $ViBar.Value = 0 } }
    else { $ViBar.Style = 'Continuous'; $ViBar.Value = [Math]::Min(100, $M.Progress) }
    $text = [string]::Join("`r`n", $M.Log.ToArray())
    if ($ViLogBox.TextLength -ne $text.Length) { $ViLogBox.Text = $text; $ViLogBox.SelectionStart = $text.Length; $ViLogBox.ScrollToCaret() }
}

function ViRunWindow {
    Add-Type -AssemblyName System.Windows.Forms, System.Drawing
    try {
        if (-not ('ViWin.ViDpi' -as [type])) { Add-Type -Namespace ViWin -Name ViDpi -MemberDefinition '[DllImport("user32.dll")] public static extern bool SetProcessDPIAware();' }
        [void][ViWin.ViDpi]::SetProcessDPIAware()
    } catch { }
    [Windows.Forms.Application]::EnableVisualStyles()
    $title = if ($InstallerCfg.publisher) { "$($InstallerCfg.publisher) apps" } else { 'Installed apps' }

    $f = New-Object Windows.Forms.Form
    $f.SuspendLayout()
    $f.AutoScaleDimensions = New-Object Drawing.SizeF(96, 96); $f.AutoScaleMode = 'Dpi'
    $f.Font = New-Object Drawing.Font('Segoe UI', 9)
    $f.Text = $title; $f.StartPosition = 'CenterScreen'
    $f.ClientSize = New-Object Drawing.Size(780, 540); $f.MinimumSize = New-Object Drawing.Size(640, 420)

    $head = New-Object Windows.Forms.Panel; $head.Dock = 'Top'; $head.Height = 60; $head.BackColor = [Drawing.SystemColors]::Window
    $h1 = New-Object Windows.Forms.Label; $h1.Text = $title; $h1.AutoSize = $true; $h1.Location = New-Object Drawing.Point(18, 10)
    $h1.Font = New-Object Drawing.Font('Segoe UI Semibold', 12)
    $h2 = New-Object Windows.Forms.Label; $h2.AutoSize = $true; $h2.Location = New-Object Drawing.Point(19, 36); $h2.ForeColor = [Drawing.SystemColors]::GrayText
    $h2.Text = 'Every download is checked against its SHA-256 before anything changes, and a failed change is put back.'
    $head.Controls.AddRange(@($h1, $h2))

    $bar = New-Object Windows.Forms.FlowLayoutPanel; $bar.Dock = 'Top'; $bar.Height = 44; $bar.Padding = New-Object Windows.Forms.Padding(14, 8, 14, 0)
    $btn = [ordered]@{}
    foreach ($b in @(@('update', 'Update'), @('change', 'Change...'), @('remove', 'Remove'), @('all', 'Update all'), @('refresh', 'Check again'), @('cancel', 'Cancel'))) {
        $x = New-Object Windows.Forms.Button; $x.Text = $b[1]; $x.AutoSize = $true; $x.MinimumSize = New-Object Drawing.Size(92, 28); $x.Tag = $b[0]
        $x.Margin = New-Object Windows.Forms.Padding(0, 0, 6, 0)
        $btn[$b[0]] = $x; [void]$bar.Controls.Add($x)
    }
    $btn.update.add_Click({ ViAct 'update' })
    $btn.change.add_Click({ ViAct 'change' })
    $btn.remove.add_Click({ ViAct 'remove' })
    $btn.all.add_Click({ ViAct 'all' })
    $btn.refresh.add_Click({ ViLoad @('*') })
    $btn.cancel.add_Click({ ViCancel })

    $list = New-Object Windows.Forms.ListView
    $list.Dock = 'Fill'; $list.View = 'Details'; $list.FullRowSelect = $true; $list.MultiSelect = $false; $list.HideSelection = $false
    $list.BorderStyle = 'None'
    foreach ($c in @(@('Application', 200), @('Installed', 90), @('Available', 90), @('Status', 360))) { [void]$list.Columns.Add($c[0], $c[1]) }
    $list.add_SelectedIndexChanged({ ViChanged })
    $empty = New-Object Windows.Forms.Label; $empty.Text = 'Nothing is installed.'; $empty.AutoSize = $true; $empty.Location = New-Object Drawing.Point(18, 40); $empty.Visible = $false
    $list.Controls.Add($empty)

    $bottom = New-Object Windows.Forms.Panel; $bottom.Dock = 'Bottom'; $bottom.Height = 200; $bottom.Padding = New-Object Windows.Forms.Padding(14, 8, 14, 12)
    $log = New-Object Windows.Forms.TextBox; $log.Dock = 'Fill'; $log.Multiline = $true; $log.ReadOnly = $true; $log.ScrollBars = 'Vertical'
    $log.Font = New-Object Drawing.Font('Consolas', 9); $log.BackColor = [Drawing.SystemColors]::Window
    $gap = New-Object Windows.Forms.Panel; $gap.Dock = 'Top'; $gap.Height = 8
    $pbar = New-Object Windows.Forms.ProgressBar; $pbar.Dock = 'Top'; $pbar.Height = 16; $pbar.MarqueeAnimationSpeed = 30
    $status = New-Object Windows.Forms.Label; $status.Dock = 'Top'; $status.Height = 22; $status.AutoEllipsis = $true
    $bottom.Controls.AddRange(@($log, $gap, $pbar, $status))

    $f.Controls.AddRange(@($list, $bar, $head, $bottom))
    $list.BringToFront()
    $f.ResumeLayout($false)

    $script:ViForm = $f; $script:ViList = $list; $script:ViBtn = $btn; $script:ViStatus = $status
    $script:ViBar = $pbar; $script:ViLogBox = $log; $script:ViEmpty = $empty
    $script:ViShown = -1

    $timer = New-Object Windows.Forms.Timer
    $timer.Interval = 100
    $timer.add_Tick({
        try {
            ViPump
            if ($M.Rev -ne $script:ViShown) { $script:ViShown = $M.Rev; ViRender }
        } catch { }
    })
    # a change that is placing files runs to its end (it is rolled back if it fails); closing waits for it
    $f.add_FormClosing({
        param($s, $e)
        if ($M.Job -and $M.Job.Phase -eq 'busy') {
            [void][Windows.Forms.MessageBox]::Show($ViForm, 'A change is being made. Close the window when it is done.', $ViForm.Text,
                [Windows.Forms.MessageBoxButtons]::OK, [Windows.Forms.MessageBoxIcon]::Information)
            $e.Cancel = $true
            return
        }
        if ($M.Job) { ViCancel }
    })
    ViLoad @('*')
    $timer.Start()
    [void][Windows.Forms.Application]::Run($f)
    $timer.Stop()
    $f.Dispose()
}

# ---- Edge front end --------------------------------------------------------------------
# The same model, shown by Microsoft Edge in app mode (a window without browser chrome) from a page this
# script serves on 127.0.0.1. Only this computer can reach it, and only with the random token in its path:
# requests must name exactly that host and port (so a web page cannot reach it through DNS rebinding), and
# changes must be POSTs from the page's own origin with an X-Vi header (which a form or another site cannot
# send without a preflight this server never answers). Edge runs with a profile of its own, so the process
# started here is that window; when it closes, or the page stops polling, the manager ends (after a change
# that is placing files has finished).

function ViFindEdge {
    $c = @(
        (Join-Path ${env:ProgramFiles(x86)} 'Microsoft\Edge\Application\msedge.exe'),
        (Join-Path $env:ProgramFiles 'Microsoft\Edge\Application\msedge.exe'),
        (Join-Path $env:LOCALAPPDATA 'Microsoft\Edge\Application\msedge.exe'))
    foreach ($p in $c) { if ($p -and (Test-Path -LiteralPath $p)) { return $p } }
    try {
        $k = (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths\msedge.exe' -ErrorAction Stop).'(default)'
        if ($k -and (Test-Path -LiteralPath $k)) { return $k }
    } catch { }
    $null
}

function ViStateJson([string]$title) {
    $apps = @()
    foreach ($a in $M.Apps.Values) {
        $o = $a.Record.options
        $apps += [ordered]@{
            id = $a.Id; name = $a.Name; version = [string]$a.Record.version; latest = $a.Latest; state = $a.State; message = $a.Message
            dir = $a.Record.installDir; hasManifest = [bool]$a.Manifest
            options = [ordered]@{ noShortcuts = [bool]$o.noShortcuts; noPath = [bool]$o.noPath; noAssociations = [bool]$o.noAssociations }
            choices = ViChoices $a $a.Record.version
        }
    }
    $job = if ($M.Job) { [ordered]@{ id = $M.Job.Id; kind = $M.Job.Kind; phase = $M.Job.Phase } } else { $null }
    $log = @($M.Log.ToArray() | Select-Object -Last 300)
    $canCancel = [bool]($M.Job -and $M.Job.Phase -ne 'busy') -or $M.Queue.Count -gt 0
    ([ordered]@{ rev = $M.Rev; title = $title; apps = $apps; job = $job; status = $M.Status; progress = $M.Progress; canCancel = $canCancel; log = $log }) |
        ConvertTo-Json -Depth 6 -Compress
}

function ViSend($ctx, [int]$code, [string]$type, [string]$text) {
    try {
        $r = $ctx.Response
        $r.StatusCode = $code
        $r.ContentType = $type
        $r.Headers['Cache-Control'] = 'no-store'
        $r.Headers['X-Content-Type-Options'] = 'nosniff'
        $b = [Text.Encoding]::UTF8.GetBytes($text)
        $r.ContentLength64 = $b.Length
        $r.OutputStream.Write($b, 0, $b.Length)
        $r.Close()
    } catch { try { $ctx.Response.Abort() } catch { } }
}

function ViReadBody($ctx) {
    $sr = New-Object IO.StreamReader($ctx.Request.InputStream, [Text.Encoding]::UTF8)
    try { $t = $sr.ReadToEnd() } finally { $sr.Dispose() }
    if (-not $t) { return $null }
    $t | ConvertFrom-Json
}

function ViServe($ctx, $srv) {
    $req = $ctx.Request
    if ([string]$req.Headers['Host'] -ne $srv.Host) { ViSend $ctx 403 'text/plain' 'Forbidden'; return }
    $path = $req.Url.AbsolutePath.Substring($srv.Token.Length + 1)
    if ($req.HttpMethod -eq 'GET') {
        if ($path -eq '/' -or $path -eq '') {
            $ctx.Response.Headers['Content-Security-Policy'] = "default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'self'; frame-ancestors 'none'"
            ViSend $ctx 200 'text/html; charset=utf-8' $srv.Page
            return
        }
        if ($path -eq '/api/state') {
            $srv.Seen = [DateTime]::Now; $srv.Bye = $null
            $have = -2
            [void][int]::TryParse([string]$req.QueryString['rev'], [ref]$have)
            if ($have -ne $M.Rev) { ViSend $ctx 200 'application/json' (ViStateJson $srv.Title) }
            else { $srv.Pending.Add([pscustomobject]@{ Ctx = $ctx; Rev = $have; Until = [DateTime]::Now.AddSeconds(15) }) }
            return
        }
        ViSend $ctx 404 'text/plain' 'Not found'
        return
    }
    if ($req.HttpMethod -ne 'POST' -or [string]$req.Headers['Origin'] -ne "http://$($srv.Host)") { ViSend $ctx 403 'text/plain' 'Forbidden'; return }
    if ($path -eq '/api/bye') { $srv.Bye = [DateTime]::Now; ViSend $ctx 200 'application/json' '{}'; return }
    if ([string]$req.Headers['X-Vi'] -ne '1') { ViSend $ctx 403 'text/plain' 'Forbidden'; return }
    try { $body = ViReadBody $ctx } catch { ViSend $ctx 400 'text/plain' 'Bad request'; return }
    switch ($path) {
        '/api/act' {
            $close = [bool]$body.closeApps
            switch ([string]$body.kind) {
                'all' { ViUpdateAll $close }
                'check' { ViLoad @('*') }
                'cancel' { ViCancel }
                { $_ -in 'update', 'change', 'remove' } { ViEnqueue ([string]$body.kind) ([string]$body.id) $body.options $close }
                default { ViSend $ctx 400 'text/plain' 'Unknown action'; return }
            }
            ViSend $ctx 200 'application/json' '{"ok":true}'
        }
        '/api/running' {
            $a = $M.Apps[[string]$body.id]
            $names = @()
            if ($a) { $names = @(ViRunningFrom $a.Record.installDir | ForEach-Object { "$($_.Name) (process $($_.ProcessId))" }) }
            ViSend $ctx 200 'application/json' (ConvertTo-Json -Compress @{ names = $names })
        }
        default { ViSend $ctx 404 'text/plain' 'Not found' }
    }
}

function ViRunEdge([string]$edge) {
    $title = if ($InstallerCfg.publisher) { "$($InstallerCfg.publisher) apps" } else { 'Installed apps' }
    $l = New-Object Net.HttpListener
    $port = 0
    for ($try = 0; $try -lt 10 -and -not $l.IsListening; $try++) {
        $port = Get-Random -Minimum 49152 -Maximum 65000
        $token = ([guid]::NewGuid().ToString('N') + [guid]::NewGuid().ToString('N'))
        $l = New-Object Net.HttpListener
        $l.Prefixes.Add("http://127.0.0.1:$port/$token/")
        try { $l.Start() } catch { }
    }
    if (-not $l.IsListening) { throw 'no free port on 127.0.0.1' }
    $srv = [pscustomobject]@{
        Host = "127.0.0.1:$port"; Token = $token; Title = $title; Seen = [DateTime]::Now; Bye = $null
        Page = $ViPage.Replace('__TITLE__', [Net.WebUtility]::HtmlEncode($title))
        Pending = New-Object 'System.Collections.Generic.List[object]'
    }
    $profileDir = Join-Path (Split-Path (ViRegistryDir) -Parent) 'manager\edge'
    ViLoad @('*')
    $url = "http://127.0.0.1:$port/$token/"
    # for tests only: where to write the page's address, so a test can drive the same API the page does
    if ($env:VI_MANAGER_URL_FILE) { [IO.File]::WriteAllText($env:VI_MANAGER_URL_FILE, $url) }
    $proc = Start-Process -FilePath $edge -PassThru -ArgumentList "--app=$url", "--user-data-dir=`"$profileDir`"", '--no-first-run',
        '--no-default-browser-check', '--window-size=980,760', '--disable-features=msEdgeSidebarV2,Translate'
    $next = $l.GetContextAsync()
    try {
        while ($true) {
            ViPump
            while ($next.IsCompleted) {
                if ($next.Status -eq 'RanToCompletion') { try { ViServe $next.Result $srv } catch { try { $next.Result.Response.Abort() } catch { } } }
                $next = $l.GetContextAsync()
            }

            $now = [DateTime]::Now
            for ($i = $srv.Pending.Count - 1; $i -ge 0; $i--) {
                $p = $srv.Pending[$i]
                if ($p.Until -le $now -or $p.Rev -ne $M.Rev) {
                    $srv.Pending.RemoveAt($i)
                    ViSend $p.Ctx 200 'application/json' (ViStateJson $srv.Title)
                }
            }
            # the window is gone: Edge exited, it said goodbye and did not come back, or it stopped polling
            $gone = $proc.HasExited -or ($srv.Bye -and ($now - $srv.Bye).TotalSeconds -gt 3) -or ($now - $srv.Seen).TotalSeconds -gt 45
            if ($gone) {
                if ($M.Job -and $M.Job.Phase -eq 'busy') { }        # placing files: let it finish
                elseif ($M.Job -or $M.Queue.Count -gt 0) { ViCancel }
                else { break }
            }
            Start-Sleep -Milliseconds 15
        }
    } finally {
        foreach ($p in $srv.Pending) { try { $p.Ctx.Response.Abort() } catch { } }
        $l.Stop(); $l.Close()
        if (-not $proc.HasExited) { & taskkill.exe /PID $proc.Id /T /F 2>&1 | Out-Null }
    }
}

# The page the Edge front end serves; __TITLE__ is replaced. Plain HTML, CSS and script, nothing loaded from elsewhere.
$ViPage = @'
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>__TITLE__</title>
<style>
  :root {
    --accent: #2563eb; --bg: #050608; --bg-2: #0b0d12; --panel: #10131a; --line: #1f2430; --line-2: #2c3342;
    --text: #f2f4f8; --muted: #9aa3b5; --dim: #5f6879; --cyan: #3ee0ff; --violet: #8b5cf6; --lime: #b6f23c; --red: #ff5d73;
    --amber: #ffc04d; --grad: linear-gradient(100deg, var(--cyan), var(--accent) 55%, var(--violet));
    --mono: ui-monospace, "Cascadia Code", "SF Mono", Consolas, monospace;
    color-scheme: dark;
  }
  * { box-sizing: border-box; }
  html, body { height: 100%; }
  body { margin: 0; background: var(--bg); color: var(--text); font: 15px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
         display: flex; flex-direction: column; overflow: hidden; }
  header { padding: 22px 28px 14px; border-bottom: 1px solid var(--line); background: var(--bg-2); }
  .eyebrow { font: 700 0.72rem/1 var(--mono); letter-spacing: 0.2em; text-transform: uppercase; color: var(--cyan); }
  h1 { margin: 8px 0 4px; font-size: 1.7rem; letter-spacing: -0.03em; font-weight: 900; background: var(--grad);
       -webkit-background-clip: text; background-clip: text; color: transparent; width: fit-content; }
  .sub { color: var(--muted); font-size: 0.88rem; margin: 0; }
  .bar { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 14px; }
  button { appearance: none; border: 1px solid var(--line-2); background: var(--panel); color: var(--text); border-radius: 4px;
           font: 700 0.86rem system-ui, sans-serif; padding: 8px 14px; cursor: pointer; }
  button:hover:not(:disabled) { border-color: var(--cyan); }
  button:focus-visible { outline: 2px solid var(--cyan); outline-offset: 2px; }
  button.primary { background: var(--text); color: var(--bg); border-color: var(--text); }
  button.danger:hover:not(:disabled) { border-color: var(--red); color: var(--red); }
  button:disabled { opacity: 0.4; cursor: default; }
  main { flex: 1; overflow-y: auto; padding: 18px 28px; display: flex; flex-direction: column; gap: 10px; }
  .empty { color: var(--muted); padding: 40px 0; text-align: center; }
  .app { background: var(--panel); border: 1px solid var(--line); border-radius: 6px; padding: 14px 16px; }
  .app.update { border-color: rgba(62,224,255,0.45); box-shadow: 0 0 24px rgba(37,99,235,0.18); }
  .app.error { border-color: rgba(255,93,115,0.5); }
  .row { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
  .name { font-weight: 800; font-size: 1.02rem; }
  .ver { font: 0.84rem var(--mono); color: var(--muted); }
  .ver b { color: var(--lime); font-weight: 700; }
  .state { font-size: 0.86rem; color: var(--muted); flex: 1; min-width: 160px; }
  .app.error .state { color: var(--red); }
  .app.update .state { color: var(--cyan); }
  .acts { display: flex; gap: 6px; margin-left: auto; }
  .dir { font: 0.78rem var(--mono); color: var(--dim); margin-top: 6px; overflow-wrap: anywhere; }
  .change { margin-top: 12px; padding-top: 12px; border-top: 1px solid var(--line); display: grid; gap: 10px; }
  .change label { display: flex; gap: 10px; align-items: center; font-size: 0.9rem; }
  .change input[type=text] { width: 100%; background: #07080b; border: 1px solid var(--line-2); color: var(--text); border-radius: 4px;
                             padding: 8px 10px; font: 0.86rem var(--mono); }
  .change input[type=checkbox] { accent-color: var(--cyan); width: 16px; height: 16px; }
  .change .hint { color: var(--dim); font-size: 0.8rem; }
  footer { border-top: 1px solid var(--line); background: var(--bg-2); padding: 12px 28px 16px; }
  .status { font-size: 0.86rem; color: var(--muted); min-height: 1.3em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .progress { height: 6px; background: var(--line); border-radius: 3px; overflow: hidden; margin: 8px 0; }
  .progress div { height: 100%; width: 0; background: var(--grad); transition: width 0.15s; }
  .progress.busy div { width: 30%; animation: slide 1.1s linear infinite; }
  @keyframes slide { from { margin-left: -30%; } to { margin-left: 100%; } }
  details summary { cursor: pointer; color: var(--dim); font-size: 0.8rem; }
  pre { margin: 8px 0 0; max-height: 170px; overflow: auto; background: #07080b; border: 1px solid var(--line); border-radius: 4px;
        padding: 10px 12px; font: 0.76rem/1.45 var(--mono); color: var(--muted); white-space: pre-wrap; }
  dialog { background: var(--panel); color: var(--text); border: 1px solid var(--line-2); border-radius: 8px; max-width: 480px; padding: 20px 22px; }
  dialog::backdrop { background: rgba(0,0,0,0.6); }
  dialog p { margin: 0 0 16px; white-space: pre-wrap; }
  dialog .acts { justify-content: flex-end; }
  .lost { position: fixed; inset: 0; background: rgba(5,6,8,0.92); display: none; align-items: center; justify-content: center;
          text-align: center; color: var(--muted); padding: 20px; }
  .lost.on { display: flex; }
</style>
</head>
<body>
<header>
  <div class="eyebrow">Installed apps</div>
  <h1 id="title">__TITLE__</h1>
  <p class="sub">Every download is checked against its SHA-256 before anything changes, and a failed change is put back.</p>
  <div class="bar">
    <button id="all" class="primary">Update all</button>
    <button id="check">Check again</button>
    <button id="cancel">Cancel</button>
  </div>
</header>
<main id="apps"><div class="empty">Loading...</div></main>
<footer>
  <div class="status" id="status"></div>
  <div class="progress" id="progress"><div></div></div>
  <details><summary>Log</summary><pre id="log"></pre></details>
</footer>
<dialog id="ask"><p id="ask-text"></p><div class="acts" id="ask-acts"></div></dialog>
<div class="lost" id="lost"><div>The manager stopped. Close this window, and open it again from the Start menu.</div></div>
<script>
"use strict";
const base = location.pathname.replace(/\/$/, "");
let state = null, rev = -1, open = null, failures = 0;
const $ = (id) => document.getElementById(id);
const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };

async function api(path, body) {
  const r = await fetch(base + "/api/" + path, body === undefined ? { cache: "no-store" } :
    { method: "POST", headers: { "Content-Type": "application/json", "X-Vi": "1" }, body: JSON.stringify(body) });
  if (!r.ok) throw new Error(r.status + " " + r.statusText);
  return r.json();
}

function ask(text, buttons) {
  return new Promise((resolve) => {
    $("ask-text").textContent = text;
    const acts = $("ask-acts"); acts.replaceChildren();
    buttons.forEach(([label, value, cls]) => {
      const b = el("button", cls || "", label);
      b.onclick = () => { $("ask").close(); resolve(value); };
      acts.append(b);
    });
    $("ask").oncancel = () => resolve(null);
    $("ask").showModal();
    acts.lastChild.focus();
  });
}

// what is running from an install folder: close it first (true), leave it (false), or stop (null)
async function running(app, what) {
  const r = await api("running", { id: app.id });
  if (!r.names.length) return false;
  const list = r.names.join("\n");
  if (what === "remove") return await ask(app.name + " is running:\n\n" + list + "\n\nIt will be closed before it is removed.", [["Close it and remove", true, "danger"], ["Cancel", null]]);
  return await ask(app.name + " is running:\n\n" + list + "\n\nClose it first? Otherwise the files it is not using are replaced now, and it is updated the next time it starts.",
    [["Close it", true, "primary"], ["Leave it running", false], ["Cancel", null]]);
}

async function act(kind, app, options) {
  if (kind === "remove") {
    const go = await ask("Remove " + app.name + " " + app.version + " from\n" + app.dir + "?", [["Remove", true, "danger"], ["Cancel", null]]);
    if (!go) return;
  }
  const close = await running(app, kind);
  if (close === null) return;
  open = null;
  await api("act", { kind, id: app.id, options: options || null, closeApps: close });
}

function renderApp(a) {
  const card = el("section", "app " + a.state);
  const row = el("div", "row");
  row.append(el("span", "name", a.name));
  const ver = el("span", "ver", a.version);
  if (a.latest && a.state === "update") { ver.append(" " + String.fromCharCode(8594) + " "); ver.append(el("b", null, a.latest)); }
  row.append(ver, el("span", "state", a.message));
  const acts = el("div", "acts");
  const idle = a.state !== "busy" && a.state !== "queued";
  const up = el("button", "primary", "Update"); up.disabled = !(idle && a.state === "update"); up.onclick = () => act("update", a);
  const ch = el("button", "", open === a.id ? "Close" : "Change..."); ch.disabled = !(idle && a.hasManifest);
  ch.onclick = () => { open = open === a.id ? null : a.id; render(); };
  const rm = el("button", "danger", "Remove"); rm.disabled = !idle; rm.onclick = () => act("remove", a);
  acts.append(up, ch, rm);
  row.append(acts);
  card.append(row, el("div", "dir", a.dir));
  if (open === a.id) {
    const f = el("div", "change");
    const dl = el("label"); dl.style.display = "grid"; dl.append(el("span", null, "Install folder (it is moved when this changes)"));
    const dir = el("input"); dir.type = "text"; dir.value = a.dir; dir.spellcheck = false; dl.append(dir); f.append(dl);
    const boxes = [];
    [["noShortcuts", "shortcuts", "Shortcuts on the desktop / in the Start menu"], ["noPath", "path", "On the user PATH"], ["noAssociations", "assoc", "Opens its file types"]]
      .forEach(([key, choice, text]) => {
        if (!a.choices[choice]) return;   // only what this version has
        const l = el("label"); const cb = el("input"); cb.type = "checkbox"; cb.checked = !a.options[key];
        l.append(cb, el("span", null, text)); f.append(l); boxes.push([key, cb]);
      });
    if (!boxes.length) f.append(el("div", "hint", "This version makes no shortcuts, PATH entries or file types."));
    const go = el("button", "primary", "Apply");
    go.onclick = () => { const o = { dir: dir.value.trim() }; boxes.forEach(([k, cb]) => { if (!cb.disabled) o[k] = !cb.checked; }); act("change", a, o); };
    const bar = el("div", "acts"); bar.style.marginLeft = "0"; bar.append(go);
    f.append(el("div", "hint", "Applied by reinstalling " + a.version + " with these choices."), bar);
    card.append(f);
  }
  return card;
}

function render() {
  if (!state) return;
  document.title = state.title; $("title").textContent = state.title;
  const apps = $("apps"); const keep = apps.scrollTop;
  const focused = document.activeElement && document.activeElement.closest(".change");
  if (!focused) {
    apps.replaceChildren(...(state.apps.length ? state.apps.map(renderApp) : [el("div", "empty", "Nothing is installed.")]));
    apps.scrollTop = keep;
  }
  $("all").disabled = !state.apps.some((a) => a.state === "update");
  $("cancel").disabled = !state.canCancel;
  $("status").textContent = state.status;
  const p = $("progress");
  p.classList.toggle("busy", !!state.job && state.progress < 0);
  p.firstChild.style.width = state.progress >= 0 ? state.progress + "%" : (state.job ? "" : "0");
  const log = $("log"); const atEnd = log.scrollTop + log.clientHeight >= log.scrollHeight - 4;
  log.textContent = state.log.join("\n"); if (atEnd) log.scrollTop = log.scrollHeight;
}

async function poll() {
  for (;;) {
    try {
      const s = await api("state?rev=" + rev);
      failures = 0; $("lost").classList.remove("on");
      if (s.rev !== rev) { state = s; rev = s.rev; render(); }
    } catch (e) {
      if (++failures >= 3) $("lost").classList.add("on");
      await new Promise((r) => setTimeout(r, 1000));
    }
  }
}

$("all").onclick = async () => {
  let close = false;
  for (const a of state.apps.filter((x) => x.state === "update")) { const c = await running(a, "update"); if (c === null) return; close = close || c; }
  await api("act", { kind: "all", closeApps: close });
};
$("check").onclick = () => api("act", { kind: "check" });
$("cancel").onclick = () => api("act", { kind: "cancel" });
addEventListener("beforeunload", (e) => { if (state && state.job && state.job.phase === "busy") { e.preventDefault(); e.returnValue = ""; } });
addEventListener("pagehide", () => navigator.sendBeacon(base + "/api/bye?x=1", ""));
poll();
</script>
</body>
</html>
'@

# ---- console ---------------------------------------------------------------------------

function ViListConsole {
    ViLoad @('*')
    $until = (Get-Date).AddSeconds(30)
    while ((Get-Date) -lt $until -and @($M.Apps.Values | Where-Object { $_.Fetch }).Count -gt 0) { ViPumpFetches; Start-Sleep -Milliseconds 100 }
    ViPumpFetches
    if ($M.Apps.Count -eq 0) { Write-Host "Nothing is installed (no install records in $(ViRegistryDir))."; return }
    foreach ($a in $M.Apps.Values) { Write-Host ("{0,-24} {1,-12} {2,-12} {3}" -f $a.Id, $a.Record.version, $a.Latest, $a.Message) }
}

# Runs jobs to their end in the console, printing the log as it grows. $false when any failed.
function ViRunConsole([string]$kind, [string]$id, [bool]$closeApps) {
    ViLoad @('*')
    $until = (Get-Date).AddSeconds(30)
    while ((Get-Date) -lt $until -and @($M.Apps.Values | Where-Object { $_.Fetch }).Count -gt 0) { ViPumpFetches; Start-Sleep -Milliseconds 100 }
    ViPumpFetches
    if ($kind -eq 'all') { ViUpdateAll $closeApps }
    else {
        if (-not $M.Apps[$id]) { Write-Host "'$id' is not installed."; return $false }
        if ($kind -eq 'update' -and $M.Apps[$id].State -ne 'update') { Write-Host "$($M.Apps[$id].Name): $($M.Apps[$id].Message)"; return $M.Apps[$id].State -ne 'error' }
        ViEnqueue $kind $id $null $closeApps
    }
    if ($M.Queue.Count -eq 0) { Write-Host 'Everything is up to date.'; return $true }
    $shown = 0
    $failed = $false
    while ($M.Job -or $M.Queue.Count -gt 0) {
        ViPump
        while ($shown -lt $M.Log.Count) { Write-Host $M.Log[$shown]; $shown++ }
        if ($M.Job -eq $null) { if (@($M.Apps.Values | Where-Object { $_.State -eq 'error' }).Count -gt 0) { $failed = $true } }
        Start-Sleep -Milliseconds 50
    }
    ViPump
    while ($shown -lt $M.Log.Count) { Write-Host $M.Log[$shown]; $shown++ }
    if (@($M.Apps.Values | Where-Object { $_.State -eq 'error' }).Count -gt 0) { $failed = $true }
    -not $failed
}

$ViMode = 'window'; $ViId = $null; $ViClose = $false; $ViForms = $false
for ($ViI = 0; $ViI -lt $args.Count; $ViI++) {
    switch -Regex ($args[$ViI]) {
        '^-List$' { $ViMode = 'list' }
        '^-Update$' { $ViMode = 'update'; $ViI++; $ViId = $args[$ViI] }
        '^-UpdateAll$' { $ViMode = 'all' }
        '^-Remove$' { $ViMode = 'remove'; $ViI++; $ViId = $args[$ViI] }
        '^-CloseApps$' { $ViClose = $true }
        '^-Forms$' { $ViForms = $true }
        default { Write-Warning "Ignoring unknown argument: $($args[$ViI])" }
    }
}
switch ($ViMode) {
    'list' { ViListConsole }
    'window' {
        $edge = if ($ViForms) { $null } else { ViFindEdge }
        $shown = $false
        if ($edge) {
            try { ViRunEdge $edge; $shown = $true }
            catch { Write-Warning "The Edge window could not be opened ($($_.Exception.Message)); using the plain one." }
        }
        if (-not $shown) { ViRunWindow }
    }
    default { if (-not (ViRunConsole $ViMode $ViId $ViClose)) { exit 1 } }
}
